import type { ComponentProps, ReactNode } from "react";
import { cn } from "./utils";

type WorkPlanStepStatus =
    | "pending"
    | "running"
    | "completed"
    | "skipped"
    | "blocked"
    | "failed"
    | "cancelled";

type WorkPlanStepData = {
    id: string;
    title: string;
    status: WorkPlanStepStatus;
    description?: string;
    agent?: string;
    duration?: string;
    details?: ReactNode;
};

type WorkPlanStepProps = {
    step: WorkPlanStepData;
    current?: boolean;
};

type WorkPlanProps = Omit<
    ComponentProps<"section">,
    "aria-label" | "children"
> & {
    label?: string;
    steps: readonly WorkPlanStepData[];
    currentStepId?: string;
};

const stepStatusLabels: Record<WorkPlanStepStatus, string> = {
    pending: "대기 중",
    running: "진행 중",
    completed: "완료",
    skipped: "건너뜀",
    blocked: "차단됨",
    failed: "실패",
    cancelled: "취소됨",
};

function validateStep(value: unknown): value is WorkPlanStepData {
    if (!value || typeof value !== "object") return false;
    const step = value as Record<string, unknown>;
    if (typeof step.id !== "string" || !step.id.trim() ||
        typeof step.title !== "string" || !step.title.trim() ||
        typeof step.status !== "string" ||
        !Object.hasOwn(stepStatusLabels, step.status)) {
        return false;
    }
    if (step.description !== undefined &&
        (typeof step.description !== "string" || !step.description.trim())) {
        return false;
    }
    if (step.agent !== undefined &&
        (typeof step.agent !== "string" || !step.agent.trim())) {
        return false;
    }
    if (step.duration !== undefined &&
        (typeof step.duration !== "string" || !step.duration.trim())) {
        return false;
    }
    return true;
}

function WorkPlanStep({ step, current = false }: WorkPlanStepProps) {
    if (!validateStep(step)) {
        throw new Error(
            "WorkPlanStep requires a valid ID, title and status.",
        );
    }
    if (typeof current !== "boolean") {
        throw new TypeError("WorkPlanStep current must be boolean.");
    }

    return (
        <li aria-current={current ? "step" : undefined}
            data-status={step.status} data-current={current || undefined}
            className={cn(
                "flex min-w-0 items-start gap-2 text-sm",
                step.status === "failed" || step.status === "blocked"
                    ? "text-danger"
                    : "text-foreground",
            )}>
            <span aria-hidden="true"
                className="mt-0.5 size-2 shrink-0 rounded-full bg-border">
                {""}
            </span>
            <div className="min-w-0 flex-1">
                <div className="flex min-w-0 flex-wrap items-baseline gap-x-2 gap-y-1">
                    <span className="font-medium">{step.title}</span>
                    {current && (
                        <span className="text-xs font-medium text-accent">
                            현재 단계
                        </span>
                    )}
                    <span className={cn(
                        "text-xs",
                        step.status === "failed" || step.status === "blocked"
                            ? "text-danger"
                            : step.status === "running"
                                ? "text-accent"
                                : "text-muted",
                    )}>
                        {stepStatusLabels[step.status]}
                    </span>
                </div>
                {(step.agent || step.duration) && (
                    <p className="m-0 mt-0.5 text-xs text-muted">
                        {step.agent && <span>{step.agent}</span>}
                        {step.agent && step.duration && <span> · </span>}
                        {step.duration && <span>{step.duration}</span>}
                    </p>
                )}
                {step.description && (
                    <p className="m-0 mt-0.5 break-words text-xs text-muted">
                        {step.description}
                    </p>
                )}
                {step.details != null && (
                    <details className="mt-[var(--space-1)]">
                        <summary aria-label={`${step.title} 세부 정보 보기`}
                            className="cursor-pointer rounded-sm text-xs text-muted focus-visible:outline-2 focus-visible:outline-focus">
                            세부 정보 보기
                        </summary>
                        <div className="mt-1 min-w-0 break-words">
                            {step.details}
                        </div>
                    </details>
                )}
            </div>
        </li>
    );
}

function WorkPlan({
    label = "작업 계획",
    steps,
    currentStepId,
    className,
    ...props
}: WorkPlanProps) {
    if (typeof label !== "string" || !label.trim()) {
        throw new Error("WorkPlan requires a label.");
    }
    if (!Array.isArray(steps)) {
        throw new TypeError("WorkPlan steps must be an array.");
    }
    if (currentStepId !== undefined &&
        (typeof currentStepId !== "string" || !currentStepId.trim())) {
        throw new Error("WorkPlan currentStepId must be a non-empty ID.");
    }

    const ids = new Set<string>();
    for (const step of steps) {
        if (!validateStep(step) || ids.has(step.id)) {
            throw new Error(
                "WorkPlan steps need unique IDs, titles and valid statuses.",
            );
        }
        ids.add(step.id);
    }
    if (currentStepId !== undefined && !ids.has(currentStepId)) {
        throw new Error("WorkPlan currentStepId must match a step ID.");
    }

    const resolved = steps.filter((step) =>
        step.status === "completed" || step.status === "skipped"
    ).length;
    const currentId = currentStepId ??
        steps.find((step) => step.status === "running")?.id;

    return (
        <section aria-label={label} data-ui="work-plan"
            data-state={steps.length === 0 ? "empty" : "ready"}
            className={cn("min-w-0 text-foreground", className)} {...props}>
            <div className="flex min-w-0 flex-wrap items-baseline justify-between gap-x-3 gap-y-1">
                <strong className="min-w-0 text-sm font-semibold">{label}</strong>
                {steps.length > 0 && (
                    <span role="status" className="text-xs text-muted">
                        {resolved}/{steps.length}단계 처리됨
                    </span>
                )}
            </div>
            {steps.length === 0 ? (
                <p role="status" className="m-0 mt-2 text-sm text-muted">
                    계획 단계가 없습니다.
                </p>
            ) : (
                <>
                    <progress value={resolved} max={steps.length}
                        aria-label={`${label} 처리된 단계`}
                        aria-valuetext={`${resolved}/${steps.length}단계 처리됨`}
                        className={
                            "mt-[var(--space-2)] h-2 w-full " +
                            "[&::-webkit-progress-bar]:rounded-full " +
                            "[&::-webkit-progress-bar]:bg-surface-subtle " +
                            "[&::-webkit-progress-value]:rounded-full " +
                            "[&::-webkit-progress-value]:bg-accent " +
                            "[&::-moz-progress-bar]:bg-accent"
                        } />
                    <ol aria-label={`${label} 단계`}
                        className="m-0 mt-[var(--space-3)] grid list-none gap-3 p-0">
                        {steps.map((step) => (
                            <WorkPlanStep key={step.id} step={step}
                                current={step.id === currentId} />
                        ))}
                    </ol>
                </>
            )}
        </section>
    );
}

export { WorkPlan, WorkPlanStep };
export type {
    WorkPlanProps,
    WorkPlanStepData,
    WorkPlanStepProps,
    WorkPlanStepStatus,
};
